function Test-Winget {
	if( -not ( Test-Path -LiteralPath $winget ) ) {
		return $false;
	}
	try {
		$null = & $winget --version;
		return ( $LASTEXITCODE -eq 0 );
	} catch {
		return $false;
	}
}

if( -not ( Test-Winget ) ) {
	'winget not usable, installing App Installer.' | Write-Warning;
	$dir = Join-Path -Path $env:TEMP -ChildPath 'winget-install';
	New-Item -Path $dir -ItemType 'Directory' -Force | Out-Null;
	try {
		$client = [System.Net.WebClient]::new();
		$client.DownloadFile( 'https://github.com/microsoft/winget-cli/releases/latest/download/DesktopAppInstaller_Dependencies.zip', "$dir\deps.zip" );
		Expand-Archive -LiteralPath "$dir\deps.zip" -DestinationPath "$dir\deps" -Force;
		Get-ChildItem -Path "$dir\deps\x64\*.appx" | ForEach-Object -Process {
			Add-AppxPackage -Path $_.FullName -ErrorAction 'Continue';
		};
		$client.DownloadFile( 'https://aka.ms/getwinget', "$dir\winget.msixbundle" );
		Add-AppxPackage -Path "$dir\winget.msixbundle" -ErrorAction 'Continue';
	} catch {
		$_ | Write-Warning;
	}
	Remove-Item -LiteralPath $dir -Recurse -Force -ErrorAction 'SilentlyContinue';
}

# The alias can take a moment to appear after registration.
